root=Path.cwd();out=Path(__file__).parent;read=lambda p:p.read_text(encoding='utf-8-sig');save=lambda p,d:p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
assert '--push-exit0' in sys.argv;head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();remote_sha=sys.argv[sys.argv.index('--remote-sha')+1];assert re.fullmatch('[0-9a-f]{40}',head) and head==remote_sha
